INSERT INTO ORDER_INFO(PRODUCT_ORDER_ID, RECEIVER_NAME, REG_DT, SHIPPING_DT, RESULT) VALUES
( #{item.P_PRODUCT_ORDER_ID}, #{item.P_NAME}, CONVERT_TZ(NOW(3), @@GLOBAL.TIME_ZONE, 'ASIA/SEOUL'), DATE_FORMAT(CONVERT_TZ(DATE_ADD(NOW(3), INTERVAL 1 DAY), @@GLOBAL.TIME_ZONE, 'ASIA/SEOUL'), '%Y/%m/%d'), 'F' )
