	SET RESULT = #{P_RESULT} 
WHERE 
	RECEIVER_NAME = #{P_RECEIVER_NAME} 
	AND SHIPPING_DT = #{P_SHIPPING_DT} 
	AND RESULT = 'S'
	AND PRODUCT_ORDER_ID = #{P_PRODUCT_ORDER_ID}
